```
f1.c  #include "hd.h"
#include <stdio.h>
const int total = 1 << 30;
static int count = 0;
static Point pnt;
int iter;
int main() {
    for (iter = 0; iter < total; ++iter) {
        rand_point(&pnt);
        count += if_inside(&pnt);
    }
    printf("Integral on [0,1] is %lf.\n",
